-- Catalog of the route-factory options a deployment is expected to tune, in the same shape as the
-- console's deploy form (modelsphere/console web/src/modules/swiss/lib/routeDirectives.ts):
--   key, label, group, kind ("number" | "boolean" | "text"), detail, needsAdaptive (only meaningful while
--   adaptive concurrency is on). No default values here: /_route_opts fills "fallback" from route.DEFAULTS
--   (the table register_route itself uses) when it answers. Only options whose default is derived from
--   other options carry a fallback, in words.
-- Entries marked hidden = true are engine internals an operator should not need to tune: the form does
-- not offer them (they stay settable as custom keys), /_route_opts lists them under "advanced" rather
-- than "directives", and the default-drift test still covers them.
-- /_route_opts (open, read-only) serves it with each option's effective value, so the form can read the catalog from
-- the engine instead of keeping its own copy. autoconfig may set some keys on its own (noted in detail),
-- which the effective value in /_route_opts shows.
local M = {}

M.DIRECTIVES = {
  { key = "adaptive_cc", label = "Adaptive concurrency", group = "Adaptive concurrency", kind = "boolean",
    detail = "Turns the AIMD limit on. With it on, the pool limit moves between the floor and the static peer maximum on the measured decode rate (and TTFT); off, a decode rate below the threshold rejects requests outright. On by default whenever a TPS threshold exists, which is always: tps_limit_tps has a default. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and treated as unset." },
  { key = "adaptive_cc_min", label = "Adaptive floor", group = "Adaptive concurrency", kind = "number",
    fallback = "static max x floor fraction", needsAdaptive = true,
    detail = "Absolute floor for the AIMD limit, in requests. Wins over the floor fraction. Must be at least 1; anything less is logged and ignored. Clamped to the static maximum." },
  { key = "adaptive_cc_min_frac", label = "Floor fraction", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Floor as a fraction of the static peer maximum, used when no absolute floor is set. Must be over 0 and at most 1; anything else is logged and the global default stands. Overload can push the limit down to the floor." },
  { key = "adaptive_cc_init", label = "Start point", group = "Adaptive concurrency", kind = "number",
    fallback = "the floor", needsAdaptive = true,
    detail = "Where a fresh or expired limit starts, in requests, and the lowest point light traffic can shrink it to. Only overload goes below it, down to the floor; once healthy again the limit climbs back to it by the climb multiplier per step. Must be at least 1. Clamped into [floor, static maximum] every time it is used; a value outside that range at startup is logged once." },
  { key = "adaptive_cc_init_frac", label = "Start fraction", group = "Adaptive concurrency", kind = "number",
    fallback = "the floor", needsAdaptive = true,
    detail = "The start point as a fraction of the static peer maximum, used when no absolute start point is set. Must be over 0 and at most 1. A fraction that lands below the floor is the same as no start point." },
  { key = "adaptive_cc_hold_when_idle", label = "Hold when idle", group = "Adaptive concurrency", kind = "boolean",
    needsAdaptive = true,
    detail = "Light or no traffic never lowers the limit: the slack shrink is skipped and the limit never expires. Growth under pressure and overload shrink are unchanged. It holds whatever value the limit has, including one an overload left low, which climbs back once traffic returns. Off restores the slack shrink and the limit TTL. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands." },
  { hidden = true, key = "adaptive_cc_inc", label = "Climb multiplier", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Applied per step when the pool is healthy and concurrency presses the limit, when requests were turned away for concurrency in the last step, and while a limit below the start point climbs back. Recovery is deliberately slower than the shrink." },
  { hidden = true, key = "adaptive_cc_dec", label = "Shrink multiplier", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Applied per step on overload -- decode rate below its threshold, or TTFT above its threshold unless TTFT judging is off -- and, with hold when idle off, by the slack shrink. Protection is fast, recovery slow." },
  { hidden = true, key = "adaptive_cc_abs", label = "Absolute headroom", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Slots the limit is kept above live concurrency, whatever the fractions say. Without it the relative band is too narrow at small concurrency, where one request flips the state and a burst has no buffer. Must be 0 or more." },
  { hidden = true, key = "adaptive_cc_pressure_frac", label = "Pressure fraction", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "The limit only climbs when live concurrency reaches this fraction of it -- otherwise light traffic walks the limit up to the maximum and a burst lands all at once. Must be over 0 and at most 1." },
  { hidden = true, key = "adaptive_cc_slack_frac", label = "Slack fraction", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Below this fraction of the limit, concurrency pulls the limit back down (not below the start point). Only acts with hold when idle off. Also sets the climb target together with the pressure fraction, so it matters either way. Must be over 0 and strictly under the pressure fraction." },
  { hidden = true, key = "adaptive_cc_ttl", label = "Limit TTL", group = "Adaptive concurrency", kind = "number",
    needsAdaptive = true,
    detail = "Seconds the computed limit survives without a decode-rate signal; past it the limit expires and the route starts again from the start point. Ignored with hold when idle on, where the limit never expires." },
  { hidden = true, key = "adaptive_cc_interval", label = "Step interval", group = "Adaptive concurrency", kind = "number",
    fallback = "the TPS window", needsAdaptive = true,
    detail = "Seconds between AIMD steps. Defaults to the TPS aggregation window, which is what the signal is measured over." },
  { key = "adaptive_cc_use_ttft", label = "Judge on TTFT too", group = "Adaptive concurrency", kind = "boolean",
    needsAdaptive = true,
    detail = "Whether a TTFT violation also shrinks the limit, or only the decode rate does. Off is for a route whose time to first token is naturally long -- prompts are big -- and which would otherwise shrink forever. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and means on." },

  { key = "tps_limit_tps", label = "Decode rate threshold", group = "Thresholds", kind = "number",
    detail = "Tokens per second per request below which the route counts as overloaded (judged on the low tail of the decode rate). Drives the adaptive limit, or rejects outright with adaptive concurrency off. An SLO requirement, when one applies, replaces it." },
  { key = "ttft_limit_ms", label = "TTFT threshold", group = "Thresholds", kind = "number",
    detail = "Milliseconds of time to first token above which the route counts as overloaded. An SLO requirement, when one applies, replaces it." },

  { key = "default_max", label = "Default peer maximum", group = "Capacity & failover", kind = "number",
    detail = "In-flight requests allowed per peer when the peer entry names no maximum of its own. The static pool maximum -- what the adaptive limit is bounded by -- is the largest per-tier sum of peer maximums." },
  { key = "load_rate_limit", label = "Load-based rate limiting", group = "Capacity & failover", kind = "boolean",
    detail = "Master switch for the load-based 429s: concurrency (the static pool limit or the adaptive one, session_prio's per-turn shares included), TTFT (session_prio's graded gate included) and decode rate. Off lets those requests through while everything behind them -- the measurements, the adaptive limit, health bans and the 503 for an all-banned pool -- keeps running, and /_rate_limit_status counts what would have been refused. Content rules (reject_rules) are not covered. A runtime override from /_rate_limit_toggle wins over this value. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands." },
  { hidden = true, key = "rt_limit_factor", label = "Runtime limit factor", group = "Capacity & failover", kind = "number",
    detail = "Scales the pool limit at which requests are turned away for concurrency: a request is refused once in-flight requests reach limit x factor. Must be over 0; anything else is logged and the global default stands." },
  { key = "max_more_tries", label = "Retry budget", group = "Capacity & failover", kind = "number",
    detail = "Upper bound on balancer retries for one request. A positive integer; anything else falls back to the default. autoconfig sets 3 on routes with a backend Service tier unless the route sets it." },
  { key = "cross_tier_fallback", label = "Cross-tier fallback", group = "Capacity & failover", kind = "boolean",
    detail = "On (the default), a 5xx or connection failure in the top tier falls straight through to one representative of each lower tier instead of waiting for the health timer to ban the peer. Off keeps a failed request inside its tier until the peer is banned. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands." },

  { hidden = true, key = "health_check_interval", label = "Probe interval", group = "Health checks", kind = "number",
    detail = "Seconds between active probes of each peer." },
  { hidden = true, key = "health_ban_ttl", label = "Ban TTL", group = "Health checks", kind = "number",
    detail = "Seconds a failing peer stays banned before it is probed back in." },
  { key = "health_probe_path", label = "Probe path", group = "Routing", kind = "text",
    detail = "Path the probe GETs. Worth overriding when a peer is itself a router, whose /v1/models answers 200 while every worker behind it is down." },
  { hidden = true, key = "cluster_avg_interval", label = "Cluster average interval", group = "Health checks", kind = "number",
    detail = "Seconds between passes of the 5-minute cluster-average concurrency. That average is shown in 429 bodies but no longer judged (the average-based check has been off since 2026-07), so this has no effect on routing." },

  { hidden = true, key = "ttft_ewma_alpha", label = "TTFT EWMA alpha", group = "TTFT measurement", kind = "number",
    detail = "Weight of the newest sample in the TTFT moving average. Higher reacts faster and is noisier. Clamped to [0, 1]." },
  { hidden = true, key = "ttft_window", label = "TTFT window", group = "TTFT measurement", kind = "number",
    detail = "Seconds the TTFT histogram aggregates over." },
  { hidden = true, key = "ttft_ttl", label = "TTFT TTL", group = "TTFT measurement", kind = "number",
    detail = "Seconds a TTFT reading stays current before it is treated as no signal." },
  { hidden = true, key = "ttft_probe_window", label = "TTFT probe window", group = "Rejection probes", kind = "number",
    detail = "Seconds over which the probe allowance below is counted." },
  { hidden = true, key = "ttft_probe_per_window", label = "TTFT probes per window", group = "Rejection probes", kind = "number",
    detail = "Requests let through per probe window while TTFT limiting is rejecting, to keep measuring whether the backend has recovered." },

  { hidden = true, key = "tps_ewma_alpha", label = "TPS EWMA alpha", group = "TPS measurement", kind = "number",
    detail = "Weight of the newest sample in the decode-rate moving average. Clamped to [0, 1]." },
  { hidden = true, key = "tps_window", label = "TPS window", group = "TPS measurement", kind = "number",
    detail = "Seconds the decode-rate histogram aggregates over, and the AIMD step interval unless that is set separately. A low tail has few samples, so a wider window is steadier." },
  { hidden = true, key = "tps_ttl", label = "TPS TTL", group = "TPS measurement", kind = "number",
    detail = "Seconds a decode-rate reading stays current before it counts as no signal." },
  { hidden = true, key = "tps_probe_window", label = "TPS probe window", group = "Rejection probes", kind = "number",
    detail = "Seconds over which the probe allowance below is counted." },
  { hidden = true, key = "tps_probe_per_window", label = "TPS probes per window", group = "Rejection probes", kind = "number",
    detail = "Requests let through per probe window while decode-rate limiting is rejecting, to keep measuring whether the backend has recovered. Decode-rate rejection only happens with adaptive concurrency off." },
  { hidden = true, key = "tps_min_tokens", label = "Minimum tokens", group = "TPS measurement", kind = "number",
    detail = "Completions shorter than this are not counted: a handful of tokens says nothing about decode rate." },
  { hidden = true, key = "tps_min_decode_s", label = "Minimum decode seconds", group = "TPS measurement", kind = "number",
    detail = "Completions decoded faster than this are not counted, for the same reason." },

  { key = "session_affinity_enabled", label = "Session affinity", group = "Routing", kind = "boolean",
    detail = "On, requests carrying a session id stick to one peer (consistent hash); off, every request goes to the least-loaded peer. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands." },
  { key = "session_prio", label = "Session turn priority", group = "Session priority", kind = "boolean",
    detail = "Shed lower-turn requests first under overload. The client gateway marks every request with x-phanrouter-session {session_id, turn}; a rejection on turn N loses the whole session and its KV cache, so once a gate starts rejecting, turn buckets (1 / 2-3 / 4-7 / ...) cede in order and warm sessions keep their slots. The adaptive limit and EWMA measurement are unchanged -- they decide how many get in; the turn decides which. Off (the default) changes nothing. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands. The runtime /_session_prio_toggle overrides this value; /_session_status shows the effective state." },
  { hidden = true, key = "session_prio_t1_probes", label = "Turn-1 probes per window", group = "Session priority", kind = "number",
    detail = "Half-open probe slots per probe window reserved for turn-1 requests at a tripped TTFT/TPS gate, on their own counter that never touches the warm probe budget. Turn 1 takes one only while no warm request has probed this window, and only under a real trip: in the turn-1 hold band (no trip, hold flag set) turn 1 gets no slot. 0 disables it (turn 1 never probes). Must be an integer of at least 0; anything else is logged and the default stands." },
  { hidden = true, key = "session_prio_r_new", label = "New-session share", group = "Session priority", kind = "number",
    detail = "Concurrency ceiling the turn-1 bucket gets, as a fraction of the pool limit. Higher buckets interpolate linearly in log2(turn) up to the full share at the full-turn mark. Must be over 0 and at most 1; anything else is logged and the default stands." },
  { hidden = true, key = "session_prio_severe", label = "Severe multiplier", group = "Session priority", kind = "number",
    detail = "TTFT/TPS EWMA past threshold x severe (or below threshold / severe) is a hard trip: every request is rejected regardless of bucket (turn 2+ and no-header requests may still take a probe slot). Must be over 1." },
  { hidden = true, key = "session_prio_full_turn", label = "Full-turn mark", group = "Session priority", kind = "number",
    detail = "Turn at and beyond which a session counts as fully warm: full concurrency share and full EWMA tolerance. Bucket bounds double 1, 2, 4, ... up to this mark. Must be an integer of at least 2." },
  { hidden = true, key = "session_prio_release", label = "Release fraction", group = "Session priority", kind = "number",
    detail = "Once TTFT has tripped, the turn-1 bucket stays rejected until the EWMA falls under threshold x this fraction (or expires). Hysteresis keeps a borderline pool from flapping new sessions in and out. Must be over 0 and under 1." },
  { hidden = true, key = "session_prio_warn_frac", label = "No-header warn fraction", group = "Session priority", kind = "number",
    detail = "When more than this fraction of a route's traffic over a minute arrives without a usable session header, a rate-limited WARN is logged (once a minute at most). No-header traffic is admitted as warm and counted separately. Must be over 0 and under 1." },
  { hidden = true, key = "session_prio_table", label = "Custom bucket table", group = "Session priority", kind = "text",
    fallback = "derived from the share/severe/full-turn options",
    detail = "Full replacement bucket table: a list of {min_turn, share, tol} entries, first min_turn 1 and strictly ascending, share over 0 up to 1, tol at least 1. Anything else is logged and the derived table stands." },
  { key = "expose_routed_peer", label = "Expose routed peer", group = "Observability", kind = "boolean",
    detail = "On, the response carries an X-Routed-Peer header naming the backend (address and GPU type) that served it. Accepts true/false (also yes/no, on/off, 1/0); anything else is logged and the default stands." },
  { hidden = true, key = "reject_rules_status", label = "Rejection status", group = "Other", kind = "number",
    detail = "HTTP status returned when a content rejection rule matches. Each rule can override it." },
  { key = "bodylog_default_pct", label = "Body log sample percent", group = "Observability", kind = "number",
    detail = "Percentage of requests whose request and response bodies are sent to the body log." },
}

return M
